function focusTick(){if(!focusRunning)return;const left=Math.max(0,Math.ceil((focusUntil-Date.now())/1000)),el=document.getElementById('focus-clock');if(el)el.textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');if(!left){focusRunning=false;focusLeft=0;focus.sessions.push({minutes:focus.duration,date:new Date().toLocaleString('ru-RU')});put('baumanka_focus_v19',focus);if(ui.page==='study'&&ui.study==='focus')renderPreservingPosition();toast('Фокус-сессия завершена')}}
