function settingsPage(){return `<div class="page bm342-settings"><h2>Настройки</h2>${compactSettings()}${section('Внешний вид · Темы и сезоны')}<div class="panel appearance-panel"><div class="bm-season-box"><div><strong>Фон темы</strong><small>Мягкий свет в цвет выбранной палитры</small></div><button class="bm-switch ${read('bm_theme_background',true)?'is-on':''}" role="switch" aria-checked="${read('bm_theme_background',true)}" aria-label="Фон темы" data-action="themebackground"><i></i></button></div><div class="bm-season-box"><div><strong>Авто-тема по времени года</strong><small>${isAutoSeason()?`Включена · сейчас активна тема «${seasonLabels[getSeasonTheme()]}»`:`Выключена · сейчас сезон «${seasonLabels[getSeasonTheme()]}»`}</small></div><button type="button" class="bm-switch ${isAutoSeason()?'is-on':''}" data-action="autoseason" role="switch" aria-checked="${isAutoSeason()}" aria-label="Автоматическая тема по времени года"><i></i></button></div><div class="sub" style="margin:14px 0 12px">Сезонные и основные темы · выбор вручную отключает авто-сезон</div><div class="theme-grid">${[['dark','☾','BMSTU Dark','Тёмная синяя'],['light','☀','BMSTU Light','Светлая синяя'],['winter','❄','Зима','Ледяной синий'],['spring','❀','Весна','Свежая мята'],['summer','☀','Лето','Тёплое солнце'],['autumn','🍂','Осень','Уютный янтарь'],['alt','✦','Violet','Фиолетовая'],['ocean','≈','Ocean','Океан'],['rose','✿','Rose','Розовая'],['forest','♣','Forest','Лесная'],['sand','◌','Sand','Песочная'],['ember','◆','Ember','Огненная'],['mono','◧','Mono','Монохром'],['gta6','✺','GTA 6','Неоновый закат'],['custom','◈','YOUR//STYLE','Своя']].map(([id,icon,name,description])=>{const active=effectiveTheme()===id;return `<button type="button" class="theme-choice ${active?'selected':''}" data-action="theme:${id}" aria-pressed="${active}"><span class="theme-swatch swatch-${id}">${icon}</span><strong>${name}</strong><small>${description}</small></button>`}).join('')}</div><div class="custom-controls"><div class="sub">Своя тема: цвет, фон и мягкость стекла. Изображение хранится только на этом устройстве.</div><label>Цвет акцентов <input id="custom-accent" type="color" value="${e(readCustomTheme().accent)}"></label><label>Прозрачность карточек <input id="custom-opacity" type="range" min="65" max="100" value="${readCustomTheme().opacity}"></label><div class="row-actions">${btn('Выбрать фон','wallpaper')}${btn('Убрать фон','wallpaperclear')}</div><input id="wallpaper-file" type="file" accept="image/*" hidden></div></div>${section('Режимы и уведомления')}<div class="panel" style="display:grid;gap:12px"><div class="bm-season-box"><div><strong>Падающий снег</strong><small>${snowEnabled()?'Включён · во всех разделах':'Выключен'}</small></div><button type="button" class="bm-switch ${snowEnabled()?'is-on':''}" data-action="togglesnow" role="switch" aria-checked="${snowEnabled()}" aria-label="Падающий снег"><i></i></button></div><div class="bm-season-box"><div><strong>Уведомления о начале пары</strong><small>${isNotifyOn()?'Включены · напоминание за 10 минут до пары':'Выключены · браузерные уведомления и тосты'}</small></div><button type="button" class="bm-switch ${isNotifyOn()?'is-on':''}" data-action="togglenotify" role="switch" aria-checked="${isNotifyOn()}" aria-label="Уведомления о начале пары"><i></i></button></div><div class="bm-season-box"><div><strong>Экзаменационный режим</strong><small>${isExamMode()?'Включён · главная показывает сессию и базу вопросов':'Выключен · обычный учебный день'}</small></div><button type="button" class="bm-switch ${isExamMode()?'is-on':''}" data-action="exammode" role="switch" aria-checked="${isExamMode()}" aria-label="Экзаменационный режим"><i></i></button></div></div>${section('Настройки главного экрана')}<div class="panel bento-profile-settings"><div class="between"><div><strong>Расположение виджетов</strong><p class="sub" style="margin:7px 0 0">Меняй порядок карточек на главной. Настройки сохраняются на этом устройстве.</p></div></div><div class="row-actions" style="margin-top:14px">${btn(bentoEditMode?'Завершить настройку':'Настроить виджеты','bentoedit','primary')}${btn('Сбросить порядок','bentoreset')}</div>${bentoEditMode?'<p class="sub" style="margin-top:10px">Режим перестановки включён. Перетащи карточки на главной, затем вернись сюда и нажми «Завершить настройку».</p>':''}</div>${section('Резервное копирование')}<div class="panel"><p class="sub">Переносит данные старого сайта, задания, баллы, экзамены, аватарку и изменения расписания. Файлы хранятся на твоём устройстве.</p><div class="row-actions">${btn(I('download')+' Скачать копию','backup','primary')}${btn('Восстановить','restore')}</div><input type="file" id="backup-file" accept="application/json,.json" hidden></div>${section('Приложение')}<div class="panel"><div class="sub">Версия приложения: ${APP_VERSION} · Liquid Glass. Данные хранятся локально. Для синхронизации между устройствами потребуется сервер.</div></div></div>`}
function photoThumbs(photos){return photos.map((p,pi)=>`<div class="task-thumb-edit"><img src="${e(p)}" alt=""><button type="button" data-action="taskphotodel:${pi}" aria-label="Удалить фото">×</button></div>`).join('')}
function updatePhotoThumbs(){const thumbs=document.querySelector('#editor .task-thumbs');if(thumbs)thumbs.innerHTML=photoThumbs(tempTaskPhotos||[])}
async function attachTaskPhotos(input){
 const form=input.form,save=form.querySelector('[type=submit]');
 const files=Array.from(input.files||[]);input.value='';
 if(tempTaskPhotos===null){const id=String(ui.sheet).split('|')[1];tempTaskPhotos=[...(data.tasks.find(x=>String(x.id)===id)?.photos||[])]}
 const draft=tempTaskPhotos;
 save.disabled=true;input.disabled=true;form.dataset.attaching='true';
 try{
   for(const file of files){
     if(draft.length>=3)break;
     if(!file.type.startsWith('image/'))continue;
     const url=URL.createObjectURL(file);
     try{
       const image=new Image();image.src=url;await image.decode();
       if(!form.isConnected||draft!==tempTaskPhotos)return;
       const canvas=document.createElement('canvas'),scale=Math.min(1,800/Math.max(image.width,image.height));
       canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));
       canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);
       draft.push(canvas.toDataURL('image/jpeg',.72));updatePhotoThumbs();
     }finally{URL.revokeObjectURL(url)}
   }
 }catch{if(form.isConnected)toast('Не удалось прочитать фотографию')}
 finally{save.disabled=false;input.disabled=false;delete form.dataset.attaching}
}
